CREATE OR REPLACE FUNCTION gb_step AS (s) ->
    if(gb_ime(s) = 1 AND gb_pending_interrupts(s) != 0,
       gb_service_interrupt(s),
       gb_dispatch(s, gb_read8(s, gb_pc(s))));
